INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_chemistry, CAST(@kp_88e57b381e AS CHAR), 'ESSAY', '【2025全国卷理综化学·第27题】<br>27．（14分）我国的蛇纹石资源十分丰富，它的主要成分是 （公式见原题） ，伴生有少量 （公式见原题） 、 （公式见原题） 、 （公式见原题） 等元素。利用蛇纹石转化与绿矾分解的耦合回收 （公式见原题） 并矿化固定二氧化碳的实验流程如图所示。<br>已知：<br>（公式见原题）<br>（公式见原题）<br>（公式见原题）<br>（公式见原题）<br>（公式见原题）<br>（公式见原题）<br>（公式见原题）<br>（公式见原题）<br>（公式见原题）<br>回答下列问题：<br>（1）绿矾（ （公式见原题） ）在高温下分解，得到红棕色固体和气体产物，反应的化学方程式为________。<br>（2）经“焙烧①”“水浸”，过滤分离后，滤液中金属离子的浓度（ （公式见原题） ）分别为： （公式见原题） 、 （公式见原题） 、 （公式见原题） 、 （公式见原题） 。滤渣①的主要成分是________、________。<br>（3）加入 （公式见原题） “调 （公式见原题） ”，过滤后，滤渣②是________、________，滤液中 （公式见原题） 的浓度为________ （公式见原题） 。<br>（4）“焙烧②”后得到 （公式见原题） 。 （公式见原题） 晶胞如图所示，晶胞中含有 （公式见原题） 的个数为________。<br>（5）调节“沉镍”后的溶液为碱性，“矿化”反应的离子方程式为________________。<br>（6） （公式见原题） 蛇纹石“矿化”固定 （公式见原题） ，得到 （公式见原题） ，相当于固定 （公式见原题） ________L（标准状况）。<div class="question-images"><img src="/images/questions/2025/chemistry/img_007.png" alt="题目配图"><img src="/images/questions/2025/chemistry/img_008.png" alt="题目配图"></div>', NULL, '（1） （公式见原题）<br>（2） （公式见原题） （公式见原题） （3） （公式见原题） （公式见原题） （公式见原题） （4）4<br>（5） （公式见原题） （6）89.6', '（1） （公式见原题）<br>（2） （公式见原题） （公式见原题） （3） （公式见原题） （公式见原题） （公式见原题） （4）4<br>（5） （公式见原题） （6）89.6', 4, '2025全国卷理综化学', @admin_id, NOW());
