INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_chemistry, CAST(@kp_3362fdb8ad AS CHAR), 'ESSAY', '【2025全国卷理综化学·第28题】<br>28．（15分）乙酸乙酯是一种应用广泛的有机化学品，可由乙酸和乙醇通过酯化反应制备。回答下列问题：<br>（1）乙酸、乙醇和乙酸乙酯的燃烧热分别为 （公式见原题） 、 （公式见原题） 和 （公式见原题） ，则酯化反应 （公式见原题） 的 （公式见原题） ____________ （公式见原题） 。<br>（2）酯化反应中的3种有机物的佛点从高到低的顺序为________原因是______________________________。<br>（3）在常压和 （公式见原题） 时，初始组成 （公式见原题） 、 （公式见原题） 作催化剂的条件下进行反应，得到乙醇浓度随反应时间的变化如下图所示。<br>平衡时乙酸的转化率 （公式见原题） ________ （公式见原题） ，平衡常数 （公式见原题） ________（保留2位有效数字）。已知酯化反应的速率方程为 （公式见原题） ，其中 （公式见原题） ，则 （公式见原题） _________ （公式见原题） （保留2位有效数字）。<br>（4）研究发现，难以通过改变反应温度或压强来提高乙酸乙酯平衡产率，原因是________________。若要提高乙酸乙酯的产率，可以采用的方法是________________（举1例）。<div class="question-images"><img src="/images/questions/2025/chemistry/img_009.png" alt="题目配图"></div>', NULL, '（1） （公式见原题）<br>（2） （公式见原题）<br>乙酸乙酯分子间不存在氢键，乙酸分子间的氢键比乙醇的更强<br>（3）303.9 （公式见原题）<br>（4） （公式见原题） 很小，温度对平衡影响小；液相反应，压强对平衡影响小及时移出产物', '（1） （公式见原题）<br>（2） （公式见原题）<br>乙酸乙酯分子间不存在氢键，乙酸分子间的氢键比乙醇的更强<br>（3）303.9 （公式见原题）<br>（4） （公式见原题） 很小，温度对平衡影响小；液相反应，压强对平衡影响小及时移出产物', 4, '2025全国卷理综化学', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 15, 28);
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_chemistry, CAST(@kp_2bc02221b8 AS CHAR), 'ESSAY', '【2025全国卷理综化学·第29题】<br>29．（15分）艾拉莫德（化合物F）有抗炎镇痛作用，可用于治疗类风湿关节炎。F的一条合成路线如下（略去部分条件和试剂）<br>回答下列问题：<br>（1）A的结构简式是________。<br>（2）B中官能团的名称是________、________。<br>（3）反应②的反应类型为________；吡啶是一种有机碱，在反应②中除了作溶剂外，还起到的作用是________________。<br>（4）在反应⑤的步骤中，二甲基丙酰氯和甲酸钠预先在溶剂丙酮中混合搅拌5小时，写出此过程的化学方程式________________。然后，再加入D进行反应。<br>（5）关于F的化学性质，下列判断错误的是________（填标号）。<br>a．可发生银镜反应 b．可发生碱性水解反应<br>c．可使 （公式见原题） 溶液显紫色 d．可使酸性 （公式见原题） 溶液褪色<br>（6）G是二甲基丙酰氯的同分异构体，可以发生银镜反应，核磁共振氢谱中显示为四组峰，且峰面积比为 （公式见原题） 。G的结构简式是________________（手性碳用*号标记）。<br>（7）参照反应①和②，利用 和 完成杀菌剂乙霉威（ ）的合成路线：<div class="question-images"><img src="/images/questions/2025/chemistry/img_010.png" alt="题目配图"><img src="/images/questions/2025/chemistry/img_011.png" alt="题目配图"><img src="/images/questions/2025/chemistry/img_012.png" alt="题目配图"><img src="/images/questions/2025/chemistry/img_013.png" alt="题目配图"><img src="/images/questions/2025/chemistry/img_014.png" alt="题目配图"></div>', NULL, '（1）<br>（2）氨基醚键<br>（3）取代反应吸收反应产生的 （公式见原题） ，促进反应进行<br>（4）<br>（5）c<br>（6）<br>（7）', '（1）<br>（2）氨基醚键<br>（3）取代反应吸收反应产生的 （公式见原题） ，促进反应进行<br>（4）<br>（5）c<br>（6）<br>（7）', 4, '2025全国卷理综化学', @admin_id, NOW());
