INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_b90100844e AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷生物·第2题】<br>2. 在一定温度下，生长在大田的某种植物光合速率（CO2固定速率）和呼吸速率（CO2释放速率）对光照强度的响应曲线如图所示。下列叙述错误的是（）<div class="question-images"><img src="/images/questions/2025/biology/img_001.png" alt="题目配图"></div>', '["光照强度为a时，该植物的干重不会增加", "光照强度从a逐渐增加到b时，该植物生长速率逐渐增大", "光照强度小于b时，提高大田CO2浓度，CO2固定速率会增大", "光照强度为b时，适当降低光反应速率，CO2固定速率会降低"]', 'C', '', 3, '2025高考课标卷生物', @admin_id, NOW());
