INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_d3501f6e77 AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷生物·第3题】<br>3. 为研究肾上腺的生理机能，某研究小组将小鼠按照下表进行处理，一定时间后检测相关指标。<br>分组<br>实验处理<br>甲<br>不摘除肾上腺<br>乙<br>摘除肾上腺<br>丙<br>摘除肾上腺，注射醛固酮<br>下列叙述错误的是（）', '["乙组小鼠的促肾上腺皮质激素水平会升高", "乙组小鼠饮生理盐水有利于改善水盐平衡", "三组小鼠均饮清水时，丙组小鼠血钠含量最低", "甲组小鼠受寒冷刺激时，肾上腺素释放量增加"]', 'C', '', 3, '2025高考课标卷生物', @admin_id, NOW());
