INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_a0f0ef1108 AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷生物·第4题】<br>4. 某同学在甲、乙两个植物群落中设置样方调查其特征，样方中植物的物种数随样方面积扩大而逐渐增加，但样方面积扩大到一定程度后物种数的变化明显趋缓（如图所示），此时对应的样方面积（a和b）通常称为最小面积。下列叙述错误的是（）', '["最小面积样方中应包含群落中绝大多数的物种", "与甲相比，乙群落的物种丰富度较高，调查时最小面积更大", "调查甲群落的物种丰富度时，设置的样方面积应不小于a", "调查乙群落中植物的种群密度时，针对每种植物设置的样方面积应不小于b"]', 'D', '', 3, '2025高考课标卷生物', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 6, 4);
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_324f0869ea AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷生物·第5题】<br>5. 为获得作物新品种，可采用不同的育种技术。下列叙述错误的是（）', '["三倍体西瓜育种时，利用了人工诱导染色体加倍获得的多倍体", "作物单倍体育种时，利用了由植物茎尖组织培养获得的单倍体", "航天育种时，利用了太空多种因素导致基因突变产生的突变体", "水稻杂交育种时，利用了水稻有性繁殖过程中产生的重组个体"]', 'B', '', 3, '2025高考课标卷生物', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 6, 5);
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_19e71442ab AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷生物·第6题】<br>6. 琼脂糖凝胶电泳常用于核酸样品的分析，样品1～4的电泳结果如图所示（“+”“-”分别代表电泳槽的阳极和阴极）。已知样品1和2中的DNA分子分别是甲和乙，甲只有限制酶R的一个酶切位点，样品3和4中有一个样品是甲的酶切产物。下列叙述错误的是（）<div class="question-images"><img src="/images/questions/2025/biology/img_003.png" alt="题目配图"></div>', '["配制琼脂糖凝胶时需选用适当 缓冲溶液", "该实验条件下甲、乙两种DNA分子均带负电荷", "甲、乙两种DNA分子所含碱基对的数量可能不同", "据图推测样品3可能是甲被酶R完全酶切后的产物"]', 'D', '', 3, '2025高考课标卷生物', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 6, 6);
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_dbab295fc6 AS CHAR), 'ESSAY', '【2025高考课标卷生物·第7题】<br>7. 将某植物叶肉细胞放入一定浓度 KCl溶液中，起初细胞失水发生质壁分离，一定时间（t）后细胞开始吸水，并逐渐复原。回答下列问题：<br>（1）植物细胞与外界溶液进行水分交换时，水分子跨膜运输的两种方式是________。<br>（2）细胞失水发生质壁分离，原生质层与细胞壁分离的原因是________。<br>（3）一定时间（t）后细胞开始吸水的原因是________。', NULL, '（1）自由扩散、协助扩散<br>（2）细胞失水体积缩小，原生质层比细胞壁的伸缩性大<br>（3）K+和C1-进入细胞，使细胞内渗透压高于外界溶液', '（1）自由扩散、协助扩散<br>（2）细胞失水体积缩小，原生质层比细胞壁的伸缩性大<br>（3）K+和C1-进入细胞，使细胞内渗透压高于外界溶液', 3, '2025高考课标卷生物', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 15, 7);
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_8ee639aa38 AS CHAR), 'ESSAY', '【2025高考课标卷生物·第8题】<br>8. 有研究显示，机体内蛋白P表达量降低会引起免疫失调。已知酶E可催化蛋白P基因的启动子甲基化，酶E被磷酸化后失活。研究人员用酶E（或磷酸化的酶E）、含蛋白P基因及其启动子的表达质粒等进行实验，结果如图所示。回答下列问题：<br>（1）免疫失调包括过敏反应和________（答出2点即可）等。<br>（2）根据实验结果判断，蛋白P基因的启动子甲基化________（填“促进”“抑制”或“不影响”）蛋白P的表达，判断依据是________。<br>（3）为治疗因蛋白P表达量降低起的免疫失调，可使用抑制________（填“酶E”“磷酸化的酶E”或“蛋白P”）活性的药物。免疫失调也可以通过调节抗体的生成进行治疗，机体产生抗体过程中记忆B细胞的作用是________。<div class="question-images"><img src="/images/questions/2025/biology/img_004.png" alt="题目配图"></div>', NULL, '（1）自身免疫病、免疫缺陷病<br>（2） ①. 抑制 ②. 酶E催化蛋白P基因的启动子甲基化，酶E含量增加导致蛋白P的表达量下降，磷酸化的酶E含量增加不会影响蛋白P的表达量<br>（3） ①. 酶E ②. 再次接触抗原时，能迅速增殖分化，快速产生大量抗体', '（1）自身免疫病、免疫缺陷病<br>（2） ①. 抑制 ②. 酶E催化蛋白P基因的启动子甲基化，酶E含量增加导致蛋白P的表达量下降，磷酸化的酶E含量增加不会影响蛋白P的表达量<br>（3） ①. 酶E ②. 再次接触抗原时，能迅速增殖分化，快速产生大量抗体', 3, '2025高考课标卷生物', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 15, 8);
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_a0f0ef1108 AS CHAR), 'ESSAY', '【2025高考课标卷生物·第9题】<br>9. 在“绿水青山就是金山银山”理念的感召下，同学们积极讨论某退化荒山的生态恢复方案。A同学提出选择一种树种进行全覆盖造林；B同学提出应该种植多种草本和木本植物。回答下列问题：<br>（1）在生态恢复过程中，退化荒山会发生群落演替。通常，群落演替的类型有初生演替和次生演替，二者的区别有________（答出2点即可）。<br>（2）与A同学的方案相比，B同学的方案可能有利于控制害虫的爆发，从种间关系的角度分析其原因是________。<br>（3）为合理利用环境资源，从群落空间结构的角度考虑，设计荒山绿化方案时应遵循的原则是________（答出2点即可）。<br>（4）为维护恢复后生态系统的稳定性，需要采取的措施有________（答出2点即可）。', NULL, '（1）起点不同；速度不同<br>（2）B同学方案中植物种类多，动物种类会相应增加，物种间的竞争、捕食等关系更复杂，使害虫种群数量增长受到限制<br>（3）群落水平方向上种植不同种类 植物；群落垂直方向上种植不同高度的植物<br>（4）控制对生态系统的干扰强度；给予相应的物质、能量投入', '（1）起点不同；速度不同<br>（2）B同学方案中植物种类多，动物种类会相应增加，物种间的竞争、捕食等关系更复杂，使害虫种群数量增长受到限制<br>（3）群落水平方向上种植不同种类 植物；群落垂直方向上种植不同高度的植物<br>（4）控制对生态系统的干扰强度；给予相应的物质、能量投入', 3, '2025高考课标卷生物', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 15, 9);
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_324f0869ea AS CHAR), 'ESSAY', '【2025高考课标卷生物·第10题】<br>10. 植物合成的色素会影响花色。某二倍体植物的花色有深红、浅红和白三种表型。研究小组用甲、乙两个浅红色表型的植株进行相关实验。回答下列问题：<br>（1）甲、乙分别自交，子一代均出现浅红色：白色=3：1的表型分离比；甲和乙杂交，子一代出现深红色（丙）：浅红色：白色（丁）=1：2：1的表型分离比。综上判断，甲和乙的基因型________（填“相同”或“不同”），判断依据是________。<br>（2）丙自交子一代出现深红色：浅红色：白色=9：6：1的表型分离比，其中与丙基因型相同的个体所占比例为________。若丙与丁杂交，子一代的表型及分离比为________，其中纯合体所占比例为________。', NULL, '（1） ①. 不同 ②. 甲、乙自交的结果与甲乙杂交的结果不同<br>（2） ①. 1/4 ②. 深红色:浅红色:白色=1:2:1 ③. 1/4', '（1） ①. 不同 ②. 甲、乙自交的结果与甲乙杂交的结果不同<br>（2） ①. 1/4 ②. 深红色:浅红色:白色=1:2:1 ③. 1/4', 4, '2025高考课标卷生物', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 15, 10);
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_19e71442ab AS CHAR), 'ESSAY', '【2025高考课标卷生物·第11题】<br>11. 为在大肠杆菌中表达酶X，某同学将编码酶X的基因（目的基因）插入质粒P0，构建重组质粒Px，并转入大肠杆菌。该同学设计引物用PCR方法验证重组质粒构建成功（引物1~4结合位置如图所示，→表示引物5＇→3＇方向）。回答下列问题：<br>（1）PCR是根据DNA复制原理在体外扩增DNA的技术。在细胞中DNA复制时解开双链的酶是________，而PCR过程中解开双链的方法是________。<br>（2）PCR过程中，因参与合成反应、不断消耗而浓度下降的组分有________。<br>（3）该同学进行PCR实验时，所用模板与引物见下表。实验中①和④的作用是：________；②无扩增产物，原因是________；③、⑤和⑥有扩增产物，扩增出的DNA产物分别是________。<br>管号<br>①<br>②<br>③<br>④<br>⑤<br>⑥<br>模板<br>无<br>P0<br>Px<br>无<br>P0<br>Px<br>引物对<br>引物1和引物2<br>引物3和引物4<br>（4）设计实验验证大肠杆菌表达 酶X有活性，简要写出实验思路和预期结果________。<div class="question-images"><img src="/images/questions/2025/biology/img_005.png" alt="题目配图"></div>', NULL, '（1） ①. 解旋酶 ②. 高温变性<br>（2）引物、脱氧核苷三磷酸<br>（3） ①. 作为对照（或答:鉴定反应体系是否有模板污染） ②. P0不含与引物1和引物2互补的碱基序列 ③. 目的基因、质粒片段、含目的基因和部分质粒序列的片段<br>（4）提取酶X，催化相应底物（反应物）的反应，检测是否有产物生成。有产物生成，则证明酶X有活性', '（1） ①. 解旋酶 ②. 高温变性<br>（2）引物、脱氧核苷三磷酸<br>（3） ①. 作为对照（或答:鉴定反应体系是否有模板污染） ②. P0不含与引物1和引物2互补的碱基序列 ③. 目的基因、质粒片段、含目的基因和部分质粒序列的片段<br>（4）提取酶X，催化相应底物（反应物）的反应，检测是否有产物生成。有产物生成，则证明酶X有活性', 4, '2025高考课标卷生物', @admin_id, NOW());
