INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_e282c42f81 AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷物理·第1题】<br>1. 我国自主研发的CR450动车组试验时的速度可达450km/h。若以120m/s的初速度在平直轨道上行驶的CR450动车组，匀减速运行14.4km后停止，则减速运动中其加速度的大小为（　　）', '["0.1m/s2", "0.5m/s2", "1.0m/s2", "1.5m/s2"]', 'B', '', 3, '2025高考课标卷物理', @admin_id, NOW());
