INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_86d0ca46c6 AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷物理·第2题】<br>2. “天都一号”通导技术试验卫星测距试验的成功，标志着我国在深空轨道精密测量领域取得了技术新突破。“天都一号”在环月椭圆轨道上运行时，（　　）', '["受月球的引力大小保持不变", "相对月球的速度大小保持不变", "离月球越近，其相对月球 速度越大", "离月球越近，其所受月球的引力越小"]', 'C', '', 3, '2025高考课标卷物理', @admin_id, NOW());
