INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_531fc8d667 AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷物理·第3题】<br>3. 如图，撑杆跳高运动中，运动员经过助跑、撑杆起跳，最终越过横杆。若运动员起跳前助跑速度为10m/s，则理论上运动员助跑获得 动能可使其重心提升的最大高度为（重力加速度取10m/s2）（　　）<div class="question-images"><img src="/images/questions/2025/physics/img_001.png" alt="题目配图"></div>', '["4m", "5m", "6m", "7m"]', 'B', '', 3, '2025高考课标卷物理', @admin_id, NOW());
