INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_329b905917 AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷物理·第4题】<br>4. 匀强电场中，一带正电的点电荷仅在电场力的作用下以某一初速度开始运动，则运动过程中，其（　　）', '["所处位置的电势一定不断降低", "所处位置的电势一定不断升高", "轨迹可能是与电场线平行 直线", "轨迹可能是与电场线垂直的直线"]', 'C', '', 3, '2025高考课标卷物理', @admin_id, NOW());
