INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_97642cdb76 AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷物理·第5题】<br>5. 如图，正方形abcd内有方向垂直于纸面的匀强磁场，电子在纸面内从顶点a以速度v0射入磁场，速度方向垂直于ab。磁感应强度的大小不同时，电子可分别从ab边的中点、b点和c点射出，在磁场中运动的时间分别为t1、t2和t3，则（）<div class="question-images"><img src="/images/questions/2025/physics/img_002.png" alt="题目配图"></div>', '["t1&lt;t2=t3", "t1&lt;t2&lt;t3", "t1=t2&gt;t3", "t1&gt;t2&gt;t3"]', 'A', '', 3, '2025高考课标卷物理', @admin_id, NOW());
