INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_7e26cc7f7a AS CHAR), 'MULTI_CHOICE', '【2025高考课标卷物理·第6题】<br>6. 如图，一定量的理想气体先后处于 （公式见原题） 图上 （公式见原题） 三个状态，三个状态下气体的压强分别为 （公式见原题） ，则（）<div class="question-images"><img src="/images/questions/2025/physics/img_003.png" alt="题目配图"></div>', '["（公式见原题）", "（公式见原题）", "（公式见原题）", "（公式见原题）"]', 'AD', '', 4, '2025高考课标卷物理', @admin_id, NOW());
