INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_8ef7997009 AS CHAR), 'MULTI_CHOICE', '【2025高考课标卷物理·第7题】<br>7. 一组身高相近的学生沿一直线等间隔排成一排，从左边第一位同学开始，依次周期性地“下蹲、起立”，整个队列呈现类似简谐波的波浪效果，如图所示。假定某次游戏中，形成的波形的波长为4m，左边第一位同学蹲至最低点时，队列中另一同学恰好站直，则这两位同学间的距离可能是（）<div class="question-images"><img src="/images/questions/2025/physics/img_004.png" alt="题目配图"></div>', '["1m", "2m", "5m", "6m"]', 'BD', '', 4, '2025高考课标卷物理', @admin_id, NOW());
