INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_8ef7997009 AS CHAR), 'MULTI_CHOICE', '【2025高考课标卷物理·第8题】<br>8. 如图，过P点的虚线上方存在方向垂直于纸面的匀强磁场。一金属圆环在纸面内以P点为轴沿顺时针方向匀速转动，O为圆环的圆心，OP为圆环的半径。则（）<div class="question-images"><img src="/images/questions/2025/physics/img_005.png" alt="题目配图"></div>', '["圆环中感应电流始终绕O逆时针流动", "OP与虚线平行时圆环中感应电流最大", "圆环中感应电流变化的周期与环转动周期相同", "圆环在磁场内且OP与虚线垂直时环中感应电流最大"]', 'BC', '', 4, '2025高考课标卷物理', @admin_id, NOW());
