INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_da1baf7adf AS CHAR), 'ESSAY', '【2025高考课标卷物理·第9题】<br>9. 某探究小组利用橡皮筋完成下面实验。<br>（1）将粘贴有坐标纸 木板竖直放置。橡皮筋的一端用图钉固定在木板上，另一端悬挂钩码。钩码质量分别为200g、250g、⋯、500g，平衡时橡皮筋底端在坐标纸上对应的位置如图（a）中圆点所示（钩码的质量在图中用数字标出）。悬挂的钩码质量分别为200g和300g时，橡皮筋底端位置间的距离为___________cm。<br>（2）根据图（a）中各点的位置可知，在所测范围内橡皮筋长度的增加量与所挂钩码的__________（选填“质量”或“质量的增加量”）成正比，由此可求出橡皮筋的劲度系数为___________ （公式见原题） （保留2位有效数字，重力加速度取 （公式见原题） ）。<br>（3）悬挂的钩码质量为 （公式见原题） 时，在橡皮筋底端施以水平向右的力 （公式见原题） ，平衡时橡皮筋方向如图（b）中虚线所示，图（b）中测力计的示数给出了力 （公式见原题） 的大小，则 （公式见原题） ___________ （公式见原题） ， （公式见原题） ___________g（选填“200”“300”或“400”）。<div class="question-images"><img src="/images/questions/2025/physics/img_006.png" alt="题目配图"><img src="/images/questions/2025/physics/img_007.png" alt="题目配图"></div>', NULL, '（1）1.90<br>（2） ①. 质量的增加量 ②. 52<br>（3） ①. 1.00 ②. 300', '（1）1.90<br>（2） ①. 质量的增加量 ②. 52<br>（3） ①. 1.00 ②. 300', 3, '2025高考课标卷物理', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 15, 9);
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_da1baf7adf AS CHAR), 'ESSAY', '【2025高考课标卷物理·第10题】<br>10. 用伏安法可以研究电学元件的伏安特性。阻值不随电流、电压变化的元件称为线性电阻元件，否则称为非线性电阻元件。<br>（1）利用伏安法测量某元件的电阻，电流表和电压表的示数分别记为 （公式见原题） 和 （公式见原题） 。若将电流表内接，则 （公式见原题） ___________元件两端的电压， （公式见原题） ___________元件的电阻；将电流表外接，则 （公式见原题） ___________流过元件的电流， （公式见原题） ___________元件的电阻。（均选填“小于”或“大于”）<br>（2）图（a）是某实验小组用电流表内接法测得的某元件的伏安特性曲线，由图可知，所测元件是__________（选填“线性”或“非线性”）电阻元件。随着电流的增加，元件的电阻__________（选填“增大”“不变”或“减小”）。<br>（3）利用电流表 （公式见原题） （内阻 （公式见原题） ）、电流表 （公式见原题） （内阻未知）以及一个用作保护电阻的定值电阻 （公式见原题） （阻值未知），测量电阻 （公式见原题） 的阻值。将图（b）中的器材符号的连线补充完整，完成实验电路原理图__________。按完整的实验电路测量 （公式见原题） ，某次测量中电流表 （公式见原题） 和 （公式见原题） 的示数分别为 （公式见原题） 和 （公式见原题） ，则 （公式见原题） ___________（用 （公式见原题） 和 （公式见原题） 表示）。<div class="question-images"><img src="/images/questions/2025/physics/img_008.png" alt="题目配图"><img src="/images/questions/2025/physics/img_009.png" alt="题目配图"></div>', NULL, '（1） ①. 大于 ②. 大于 ③. 大于 ④. 小于<br>（2） ①. 非线性 ②. 减小<br>（3） ①. ②. （公式见原题）', '（1） ①. 大于 ②. 大于 ③. 大于 ④. 小于<br>（2） ①. 非线性 ②. 减小<br>（3） ①. ②. （公式见原题）', 4, '2025高考课标卷物理', @admin_id, NOW());
