INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_c35cb6d924 AS CHAR), 'ESSAY', '【2025高考课标卷物理·第11题】<br>11. 电容器 形状变化会导致其电容变化，这一性质可用于设计键盘，简化原理图如图所示。键盘按键下的装置可视为平行板电容器，电容器的极板面积为 （公式见原题） 、间距为 （公式见原题） ，电容 （公式见原题） （ （公式见原题） 为常量）。按下键盘按键时，极板间的距离变为按压前的 （公式见原题） 倍；撤去按压，按键在弹力作用下复位。电容器充电后：<br>（1）若按压按键不改变电容器所带的电荷量，则按压后极板间的电压变为按压前的多少倍？<br>（2）若按压按键不改变电容器极板间的电压，则按压后极板间的电场强度大小变为按压前的多少倍？<div class="question-images"><img src="/images/questions/2025/physics/img_010.png" alt="题目配图"></div>', NULL, '（1） （公式见原题） 倍<br>（2） （公式见原题） 倍', '（1） （公式见原题） 倍<br>（2） （公式见原题） 倍', 4, '2025高考课标卷物理', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 15, 11);
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_15ccef12ae AS CHAR), 'ESSAY', '【2025高考课标卷物理·第12题】<br>12. 如图，物块P固定在水平面上，其上表面有半径为R的 （公式见原题） 圆弧轨道。P右端与薄板Q连在一起，圆弧轨道与Q上表面平滑连接。一轻弹簧的右端固定在Q上，另一端自由。质量为m的小球自圆弧顶端A点上方的B点自由下落，落到A点后沿圆弧轨道下滑，小球与弹簧接触后，当速度减小至刚接触时的 （公式见原题） 时弹簧的弹性势能为2mgR，此时断开P和Q的连接，从静止开始向右滑动。g为重力加速度大小，忽略空气阻力，圆弧轨道及Q的上、下表面均光滑，弹簧长度的变化始终在弹性限度内。<br>（1）求小球从落入圆弧轨道至离开圆弧轨道，重力对其做的功；<br>（2）求小球与弹簧刚接触时速度的大小及B、A两点间的距离；<br>（3）欲使P和Q断开后，弹簧的最大弹性势能等于2.2mgR，Q的质量应为多大？<br>（4）欲使P和Q断开后，Q的最终动能最大，Q的质量应为多大？', NULL, '（1） （公式见原题）<br>（2） （公式见原题） ， （公式见原题）<br>（3） （公式见原题）<br>（4） （公式见原题）', '（1） （公式见原题）<br>（2） （公式见原题） ， （公式见原题）<br>（3） （公式见原题）<br>（4） （公式见原题）', 4, '2025高考课标卷物理', @admin_id, NOW());
INSERT INTO exam_question (exam_id, question_id, score, sort_order) VALUES (@exam_id, @question_id, 15, 12);
